// ggml_new_f32 moved to ggml/src/ggml-cpu/ggml-cpu.c, per upstream 9f409893 (#10144).

void ggml_set_input_scale(struct ggml_tensor * tensor, float scale) {
    memcpy(tensor->op_params + GGML_MAX_OP_PARAMS / sizeof(int32_t) - 1, &scale, sizeof(scale));
}

float ggml_get_input_scale(const struct ggml_tensor * tensor) {
    float scale;
    memcpy(&scale, tensor->op_params + GGML_MAX_OP_PARAMS / sizeof(int32_t) - 1, sizeof(scale));
    return scale;
}

struct ggml_tensor * ggml_dup_tensor(struct ggml_context * ctx, const struct ggml_tensor * src) {
    struct ggml_tensor * result = ggml_new_tensor(ctx, src->type, GGML_MAX_DIMS, src->ne);
    if (src->type == GGML_TYPE_NVFP4_KS) {
        ggml_set_input_scale(result, ggml_get_input_scale(src));
    }
    return result;
}

// ggml_set_op_params moved to ggml-impl.h 2026-09-08 so the backend libraries can see it.
// ggml_set_op_params_i32 moved to ggml-impl.h 2026-09-08 so the backend libraries can see it.
// ggml_set_op_params_f32 moved to ggml-impl.h 2026-09-08 so the backend libraries can see it.
struct ggml_tensor * ggml_set_zero(struct ggml_tensor * tensor) {
    memset(tensor->data, 0, ggml_nbytes(tensor));
    return tensor;
}

// ggml_set_i32 moved to ggml/src/ggml-cpu/ggml-cpu.c, per upstream 9f409893 (#10144).

// ggml_set_f32 moved to ggml/src/ggml-cpu/ggml-cpu.c, per upstream 9f409893 (#10144).

void ggml_unravel_index(const struct ggml_tensor * tensor, int64_t i, int64_t * i0, int64_t * i1, int64_t * i2, int64_t * i3) {
    const int64_t ne2 = tensor->ne[2];
    const int64_t ne1 = tensor->ne[1];
    const int64_t ne0 = tensor->ne[0];

    const int64_t i3_ = (i/(ne2*ne1*ne0));
    const int64_t i2_ = (i - i3_*ne2*ne1*ne0)/(ne1*ne0);
    const int64_t i1_ = (i - i3_*ne2*ne1*ne0 - i2_*ne1*ne0)/ne0;
    const int64_t i0_ = (i - i3_*ne2*ne1*ne0 - i2_*ne1*ne0 - i1_*ne0);

    if (i0) {
        * i0 = i0_;
    }
    if (i1) {
        * i1 = i1_;
    }
    if (i2) {
        * i2 = i2_;
    }
    if (i3) {
        * i3 = i3_;
    }
}

