// ggml_dup

static struct ggml_tensor * ggml_dup_impl(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        bool inplace) {


    struct ggml_tensor * result = inplace ? ggml_view_tensor(ctx, a) : ggml_dup_tensor(ctx, a);

    result->op   = GGML_OP_DUP;
    result->src[0] = a;

    return result;
}

struct ggml_tensor * ggml_dup(
        struct ggml_context * ctx,
        struct ggml_tensor * a) {
    return ggml_dup_impl(ctx, a, false);
}

struct ggml_tensor * ggml_dup_inplace(
        struct ggml_context * ctx,
        struct ggml_tensor * a) {
    return ggml_dup_impl(ctx, a, true);
}

struct ggml_tensor * ggml_reduce(
            struct ggml_context         * ctx,
            struct ggml_tensor         ** a,
            int                           n,
            enum ggml_op                  op) {
    GGML_ASSERT(n > 1 && n <= GGML_MAX_SRC);
    GGML_ASSERT(op == GGML_OP_ADD); // currently we only handle reduce_add
    struct ggml_tensor * last = NULL;
    int nhave = 0;
    for (int j = 0; j < n; ++j) {
        if (a[j]) { ++nhave; last = a[j]; }
    }
    GGML_ASSERT(last);
    if (nhave == 1) {
        return last;
    }
    struct ggml_tensor * result = ggml_view_tensor(ctx, last);
    for (int j = 0; j < n; ++j) {
        result->src[j] = a[j];
    }
    result->op = GGML_OP_REDUCE;
    result->op_params[0] = (int)op;
    result->op_params[1] = n;
    result->op_params[2] = nhave;
    return result;
}

struct ggml_tensor * ggml_fake_cpy(
            struct ggml_context         * ctx,
            struct ggml_tensor          * dst,
            struct ggml_tensor          * src) {
    struct ggml_tensor * result = ggml_view_tensor(ctx, dst);
    result->op = GGML_OP_FAKE_CPY;
    result->src[0] = dst;
    result->src[1] = src;
    return result;
}


// ggml_add

static struct ggml_tensor * ggml_add_impl(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        struct ggml_tensor * b,
        bool inplace) {
    GGML_ASSERT(ggml_can_repeat(b, a));



    struct ggml_tensor * result = inplace ? ggml_view_tensor(ctx, a) : ggml_dup_tensor(ctx, a);

    result->op   = GGML_OP_ADD;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

struct ggml_tensor * ggml_add(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        struct ggml_tensor * b) {
    return ggml_add_impl(ctx, a, b, false);
}

struct ggml_tensor * ggml_add_inplace(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        struct ggml_tensor * b) {
    return ggml_add_impl(ctx, a, b, true);
}

// ggml_add

struct ggml_tensor * ggml_multi_add(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        int n_experts) {


    if (n_experts < 1) {
        GGML_ABORT("fatal error");
    }

    struct ggml_tensor * result = ggml_dup_tensor(ctx, a);

    result->op   = GGML_OP_MULTI_ADD;
    result->src[0] = a;
    result->op_params[0] = n_experts;

    return result;
}

struct ggml_tensor * ggml_mul_multi_add(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        struct ggml_tensor  * b) {


    GGML_ASSERT(a->ne[1] == b->ne[1]);
    GGML_ASSERT(a->ne[2] == b->ne[2]);
    GGML_ASSERT(a->ne[3] == b->ne[3]);
    GGML_ASSERT(a->ne[3] == 1);
    GGML_ASSERT(b->ne[0] == 1);

    int64_t ne[GGML_MAX_DIMS] = { a->ne[0], a->ne[2], 1, 1 };

    struct ggml_tensor * result = ggml_new_tensor(ctx, GGML_TYPE_F32, GGML_MAX_DIMS, ne);

    result->op   = GGML_OP_MUL_MULTI_ADD;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

//#if defined(_MSC_VER)
//#pragma warning(disable: 4244 4267) // possible loss of data
//#include <intrin.h>
//#include <ammintrin.h>
//#include <nmmintrin.h>
//#include <immintrin.h>
//#include <stdlib.h>
//static inline int popcount(uint32_t x) { return __popcnt(x); }
//#else
//static inline int popcount(uint32_t x) { return __builtin_popcount(x); }
//#endif

struct ggml_tensor * ggml_hadamard(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        int                   n) {

    GGML_ASSERT(n > 1);                    // no point in Hadamard transforms with less than 2 elements
    if (a->ne[0] % n != 0) {
        fprintf(stderr, "%s: head size %ld is not a multiple of block size %d for tensor %s\n", __func__, a->ne[0], n, a->name);
        GGML_ABORT("Fatal error");
    }
    if ((n & ~(n-1)) != n) {
        fprintf(stderr, "%s: block size %d is not a power of 2 for tensor %s\n", __func__, n, a->name);
        GGML_ABORT("Fatal error");
    }
    //GGML_ASSERT(a->ne[0] % n == 0);
    //GGML_ASSERT(popcount(n) == 1);         // must be a power of 2

    struct ggml_tensor * result = ggml_new_tensor(ctx, GGML_TYPE_F32, GGML_MAX_DIMS, a->ne);

    result->op   = GGML_OP_HADAMARD;
    result->src[0] = a;

    result->op_params[0] = n;

    return result;
}

struct ggml_tensor * ggml_signed_hadamard(
            struct ggml_context * ctx,
            struct ggml_tensor  * a,
            struct ggml_tensor  * signs,
            int                   n,
            int                   before) {

    // To simplify things, for now we assume the following:
    GGML_ASSERT(a->type == GGML_TYPE_F32);
    GGML_ASSERT(signs->type == GGML_TYPE_F32);
    GGML_ASSERT(ggml_is_contiguous(a) && ggml_is_contiguous(signs));
    GGML_ASSERT(a->ne[0] == signs->ne[0]);
    GGML_ASSERT(ggml_nrows(signs) == 1);

    struct ggml_tensor * result = ggml_hadamard(ctx, a, n);

    result->src[1]       = signs;
    result->op_params[1] = before;

    return result;
}


// ggml_add_cast

static struct ggml_tensor * ggml_add_cast_impl(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        struct ggml_tensor * b,
        enum   ggml_type     type) {
    // TODO: support less-strict constraint
    //       GGML_ASSERT(ggml_can_repeat(b, a));
    GGML_ASSERT(ggml_can_repeat_rows(b, a));

    // currently only supported for quantized input and f16
    GGML_ASSERT(ggml_is_quantized(a->type) ||
                a->type == GGML_TYPE_F16 ||
                a->type == GGML_TYPE_BF16);



    struct ggml_tensor * result = ggml_new_tensor(ctx, type, GGML_MAX_DIMS, a->ne);

    result->op   = GGML_OP_ADD;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

struct ggml_tensor * ggml_add_cast(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        struct ggml_tensor * b,
        enum   ggml_type     type) {
    return ggml_add_cast_impl(ctx, a, b, type);
}

// ggml_add_id

struct ggml_tensor * ggml_add_id(
            struct ggml_context * ctx,
            struct ggml_tensor  * a,
            struct ggml_tensor  * b,
            struct ggml_tensor  * ids) {

    GGML_ASSERT(a->ne[0] == b->ne[0]);
    GGML_ASSERT(a->ne[1] == ids->ne[0]);
    GGML_ASSERT(a->ne[2] == ids->ne[1]);
    GGML_ASSERT(ids->type == GGML_TYPE_I32);

    struct ggml_tensor * result = ggml_dup_tensor(ctx, a);

    result->op     = GGML_OP_ADD_ID;
    result->src[0] = a;
    result->src[1] = b;
    result->src[2] = ids;

    return result;
}

