static struct ggml_tensor * ggml_fused_mul_unary_impl(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        struct ggml_tensor * b,
        enum ggml_unary_op   op,
        bool inplace) {

    GGML_ASSERT(ggml_is_contiguous(a));
    if (!ggml_are_same_shape(b, a)) {
        GGML_ASSERT(a->ne[0] == 1 && a->ne[1] == b->ne[1] && a->ne[2] == b->ne[2] && a->ne[3] == b->ne[3]);
        GGML_ASSERT(op == GGML_UNARY_OP_SILU || op == GGML_UNARY_OP_SIGMOID);
        struct ggml_tensor * result = inplace ? ggml_view_tensor(ctx, b) : ggml_dup_tensor(ctx, b);
        ggml_set_op_params_i32(result, 0, (int32_t) op);
        result->op   = GGML_OP_FUSED_MUL_UNARY;
        result->src[0] = a;
        result->src[1] = b;
        return result;
    }
    GGML_ASSERT(op == GGML_UNARY_OP_GELU || op == GGML_UNARY_OP_RELU || op == GGML_UNARY_OP_SILU || op == GGML_UNARY_OP_SIGMOID);




    struct ggml_tensor * result = inplace ? ggml_view_tensor(ctx, a) : ggml_dup_tensor(ctx, a);

    ggml_set_op_params_i32(result, 0, (int32_t) op);

    result->op   = GGML_OP_FUSED_MUL_UNARY;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

struct ggml_tensor * ggml_fused_mul_unary(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        struct ggml_tensor  * b,
        enum ggml_unary_op op) {
    return ggml_fused_mul_unary_impl(ctx, a, b, op, false);
}

struct ggml_tensor * ggml_fused_mul_unary_inplace(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        struct ggml_tensor  * b,
        enum ggml_unary_op op) {
    return ggml_fused_mul_unary_impl(ctx, a, b, op, true);
}

