// ggml_repeat

struct ggml_tensor * ggml_repeat(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        struct ggml_tensor * b) {
    GGML_ASSERT(ggml_can_repeat(a, b));



    struct ggml_tensor * result = ggml_new_tensor(ctx, a->type, GGML_MAX_DIMS, b->ne);

    result->op   = GGML_OP_REPEAT;
    result->src[0] = a;

    return result;
}

struct ggml_tensor * ggml_repeat_4d(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        int64_t ne0, int64_t ne1, int64_t ne2, int64_t ne3) {
    const bool can_repeat = ggml_is_empty(a) || (
        (ne0 % a->ne[0] == 0) &&
        (ne1 % a->ne[1] == 0) &&
        (ne2 % a->ne[2] == 0) &&
        (ne3 % a->ne[3] == 0)
    );
    GGML_ASSERT(can_repeat);



    struct ggml_tensor * result = ggml_new_tensor_4d(ctx, a->type, ne0, ne1, ne2, ne3);

    result->op   = GGML_OP_REPEAT;
    result->src[0] = a;

    return result;
}

// ggml_repeat_back

struct ggml_tensor * ggml_repeat_back(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        struct ggml_tensor * b) {
    GGML_ASSERT(ggml_can_repeat(b, a));



    if (ggml_are_same_shape(a, b)) {
        return a;
    }

    struct ggml_tensor * result = ggml_new_tensor(ctx, a->type, GGML_MAX_DIMS, b->ne);

    result->op   = GGML_OP_REPEAT_BACK;
    result->src[0] = a;

    return result;
}

// ggml_concat

// ggml_turbo_wht — Walsh-Hadamard Transform for TurboQuant KV cache rotation
// direction: 0 = forward (pre-quantize), 1 = inverse (post-dequantize)
// group_size: 32, 64, or 128; scale_inv: InnerQ per-channel scaling tensor (may be NULL)
struct ggml_tensor * ggml_turbo_wht(
    struct ggml_context * ctx,
    struct ggml_tensor  * a,
    struct ggml_tensor  * scale_inv,
    int                   direction,
    int                   group_size) {
    GGML_ASSERT(group_size == 32 || group_size == 64 || group_size == 128);
    struct ggml_tensor * result = ggml_dup_tensor(ctx, a);
    ggml_set_op_params_i32(result, 0, direction);
    ggml_set_op_params_i32(result, 1, group_size);
    result->op     = GGML_OP_TURBO_WHT;
    result->src[0] = a;
    result->src[1] = scale_inv;  // may be NULL
    return result;
}

struct ggml_tensor * ggml_concat(
    struct ggml_context * ctx,
    struct ggml_tensor * a,
    struct ggml_tensor * b,
    int dim) {
    GGML_ASSERT(dim >= 0 && dim < GGML_MAX_DIMS);

    int64_t ne[GGML_MAX_DIMS];
    for (int d = 0; d < GGML_MAX_DIMS; ++d) {
        if (d == dim) {
            ne[d] = a->ne[d] + b->ne[d];
            continue;
        }
        GGML_ASSERT(a->ne[d] == b->ne[d]);
        ne[d] = a->ne[d];
    }



    struct ggml_tensor * result = ggml_new_tensor(ctx, a->type, GGML_MAX_DIMS, ne);

    ggml_set_op_params_i32(result, 0, dim);

    result->op = GGML_OP_CONCAT;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

struct ggml_tensor * ggml_concat_inplace(
    struct ggml_context * ctx,
    struct ggml_tensor * a,
    struct ggml_tensor * b,
    struct ggml_tensor * result_in,
    int dim) {
    GGML_ASSERT(dim >= 0 && dim < GGML_MAX_DIMS);
    if (!result_in) {
        return ggml_concat(ctx, a, b, dim);
    }

    for (int d = 0; d < GGML_MAX_DIMS; ++d) {
        int64_t ne;
        if (d == dim) {
            ne = a->ne[d] + b->ne[d];
        } else {
            GGML_ASSERT(a->ne[d] == b->ne[d]);
            ne = a->ne[d];
        }
        GGML_ASSERT(ne == result_in->ne[d]);
    }

    struct ggml_tensor * result = ggml_view_tensor(ctx, result_in);

    ggml_set_op_params_i32(result, 0, dim);

    result->op = GGML_OP_CONCAT;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

