// ggml_prec

bool ggml_prec_set_acc(
        struct ggml_tensor * a,
        enum ggml_prec       prec) {
    switch (a->op) {
        case GGML_OP_MUL_MAT:
        case GGML_OP_MUL_MAT_ID:
            {
                const int32_t prec_i32 = (int32_t) prec;
                ggml_set_op_params_i32(a, 0, prec_i32);
            }
            break;
        case GGML_OP_FLASH_ATTN_EXT:
            {
                const int32_t prec_i32 = (int32_t) prec;
                ggml_set_op_params_i32(a, 3, prec_i32);
            }
            break;
        default:
            return false;
    };

    return true;
}

bool ggml_prec_set_src(
        struct ggml_tensor * a,
        enum ggml_prec       prec,
        int                  idx) {
    GGML_ASSERT(idx >= 0 && idx < GGML_MAX_SRC);

    switch (a->op) {
        case GGML_OP_MUL_MAT:
        case GGML_OP_MUL_MAT_ID:
            {
                if (idx != 1) {
                    return false;
                }

                const int32_t prec_i32 = (int32_t) prec;
                ggml_set_op_params_i32(a, 2 + idx, prec_i32);
            }
            break;
        default:
            return false;
    };

    return true;
}

enum ggml_prec ggml_prec_get_acc(
        const struct ggml_tensor * a) {
    switch (a->op) {
        case GGML_OP_MUL_MAT:
        case GGML_OP_MUL_MAT_ID:
            return (enum ggml_prec) ggml_get_op_params_i32(a, 0);
        case GGML_OP_FLASH_ATTN_EXT:
            return (enum ggml_prec) ggml_get_op_params_i32(a, 3);
        default:
            return GGML_PREC_UNDEFINED;
    };
}

enum ggml_prec ggml_prec_get_src(
        const struct ggml_tensor * a,
        int                        idx) {
    GGML_ASSERT(idx >= 0 && idx < GGML_MAX_SRC);

    switch (a->op) {
        case GGML_OP_MUL_MAT:
        case GGML_OP_MUL_MAT_ID:
            if (idx != 1) {
                return GGML_PREC_UNDEFINED;
            }
            return (enum ggml_prec) ggml_get_op_params_i32(a, 2 + idx);
        default:
            return GGML_PREC_UNDEFINED;
    };
}

// ggml_mul_mat

struct ggml_tensor * ggml_mul_mat(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        struct ggml_tensor  * b) {
    GGML_ASSERT(ggml_can_mul_mat(a, b));
    GGML_ASSERT(!ggml_is_transposed(a));



    const int64_t ne[4] = { a->ne[1], b->ne[1], b->ne[2], b->ne[3] };
    struct ggml_tensor * result = ggml_new_tensor(ctx, GGML_TYPE_F32, 4, ne);

    result->op   = GGML_OP_MUL_MAT;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

struct ggml_tensor * ggml_mul_mat_inplace(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        struct ggml_tensor  * b,
        struct ggml_tensor  * result_in) {
    if (!result_in) {
        return ggml_mul_mat(ctx, a, b);
    }
    GGML_ASSERT(ggml_can_mul_mat(a, b));
    GGML_ASSERT(!ggml_is_transposed(a));
    GGML_ASSERT(b->ne[2] == 1 && b->ne[3] == 1);

    const int64_t ne[4] = { a->ne[1], b->ne[1], b->ne[2], b->ne[3] };
    GGML_ASSERT(result_in->type == GGML_TYPE_F32);
    GGML_ASSERT(ggml_nelements(result_in) >= ne[0]*ne[1]);

    struct ggml_tensor * result = ggml_view_2d(ctx, result_in, ne[0], ne[1], ne[0]*sizeof(float), 0);

    result->op   = GGML_OP_MUL_MAT;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

void ggml_mul_mat_set_prec(
        struct ggml_tensor * a,
        enum ggml_prec       prec) {
    GGML_ASSERT(a->op == GGML_OP_MUL_MAT);

    const int32_t prec_i32 = (int32_t) prec;

    ggml_set_op_params_i32(a, 0, prec_i32);
}

// ggml_mul_mat_id

/*
    c = ggml_mul_mat_id(ctx, as, b, ids);

    as  -> [cols, rows, n_expert]
    ids -> [n_experts_used, n_tokens] (i32)
    b   -> [cols, n_expert_used, n_tokens]
    c   -> [rows, n_expert_used, n_tokens]

    in b, n_experts_used can be broadcasted to match the n_expert_used of ids

    c ~= as[:,:,i] @ b[:,i%r,t], i = ids[e,t] for all e,t in ids

    an id of -1 skips the slot: no matrix is selected, c[:,e,t] is set to zero
*/
struct ggml_tensor * ggml_mul_mat_id(
        struct ggml_context * ctx,
        struct ggml_tensor  * as,
        struct ggml_tensor  * b,
        struct ggml_tensor  * ids) {
    GGML_ASSERT(!ggml_is_transposed(as));
    GGML_ASSERT(ids->type == GGML_TYPE_I32);

    GGML_ASSERT(as->ne[3] == 1); // as is 3d (one matrix per expert)
    GGML_ASSERT(b->ne[3] == 1); // b is 3d
    GGML_ASSERT(ids->ne[2] == 1 && ids->ne[3] == 1); // ids is 2d
    GGML_ASSERT(ids->ne[1] == b->ne[2]); // must have an expert list per b row
    //// can_mul_mat
    //if (as->ne[0] != b->ne[0]) {
    //    fprintf(stderr, "MUL_MAT_ID_FAIL: as='%s' ne[0]=%ld type=%s | b='%s' ne[0]=%ld type=%s | ids->ne[1]=%ld b->ne[2]=%ld as->ne[1]=%ld as->ne[2]=%ld\n",
    //            as->name, (long)as->ne[0], ggml_type_name(as->type),
    //            b->name, (long)b->ne[0], ggml_type_name(b->type),
    //            (long)ids->ne[1], (long)b->ne[2], (long)as->ne[1], (long)as->ne[2]);
    //    fflush(stderr);
    //}
    GGML_ASSERT(as->ne[0] == b->ne[0]); // can_mul_mat
    GGML_ASSERT(ids->ne[0] % b->ne[1] == 0); // can broadcast



    const int64_t ne[4] = { as->ne[1], ids->ne[0], b->ne[2], 1 };
    struct ggml_tensor * result = ggml_new_tensor(ctx, GGML_TYPE_F32, 4, ne);

    result->op   = GGML_OP_MUL_MAT_ID;
    result->src[0] = as;
    result->src[1] = b;
    result->src[2] = ids;

    return result;
}

// Fused up/gate needs an iqk kernel for the weight type. Where the kernel is absent the fused
// NODE must not be built at all, because the compute side calls GGML_ABORT("fatal error") when
// iqk_moe_fused_up_gate declines -- a hard abort rather than a fallback. Declining the fusion
// here is the same shape iqk_kda and iqk_mul_mat already use for shapes and types outside their
// coverage: say no, and let the generic unfused path run.
//
// COMPATIBILITY-INVESTIGATED: the alternative to declining is to ADD the fused kernels, which is
// a tracked speed item (S69-FORK-BONSAI-CUDA-PATH-MISSING-01), not a barrier -- this predicate
// is the correctness half and does not foreclose it. Kernel coverage was measured per type
// rather than assumed: TQ1_0 and TQ2_0 are refused explicitly at iqk_mul_mat.cpp:516-517, and
// Q2_0_G128 has ZERO case labels anywhere under ggml/src/iqk (one comment hit only, at
// iqk_quantize.cpp:10419) so MulMat::prepare's `default: return false` declines it. Q1_0_G128 is
// deliberately NOT listed for the opposite reason: iqk DOES implement it (iqk_mul_mat.cpp:958,
// :1050 and iqk_gemm_1bit.cpp:1966, :2951), and excluding a type that has a kernel would cost a
// working fast path rather than protect anything.
//
// CARRIED FROM feature/tq2_0-wip, which had this for TQ2_0 only, and widened to every type this
// tree already declines a layer up in llama-build-context.cpp. That higher decline protects the
// llama graph builder ONLY; ggml_moe_up_gate and ggml_fused_up_gate are ggml-layer API entries
// any consumer can call, so the guard belongs here too -- guard at the callee, not once per
// caller.
static inline bool ggml_can_fuse_up_gate_type(enum ggml_type t) {
    return ggml_iqk_supports_type(t, GGML_IQK_SITE_UP_GATE_OP);
}

// The per-site sets, each one exactly what that site's own `type != ...` chain excluded before
// it was routed here (2026-10-18). The reasons stay at the sites; this is where the sets live.
// Orphan 46c2494b8 carried ONE set {TQ2_0, Q2_0_G128} for every site; carried as written it would
// have re-excluded TQ1_0/TQ2_0/Q2_0_G128 from the dense GEMM, which now has kernels for them.
// Gyro trellis types (ik df93e4cc9 #2812): decode + vec_dot + (TQ2_T only) a dense iqk GEMM; no fused up/gate, no MoE kernel.
static inline bool ggml_is_tq_trellis_type(enum ggml_type type) {
    return type == GGML_TYPE_TQ2_T || type == GGML_TYPE_TQK6 || type == GGML_TYPE_TQK7 ||
           type == GGML_TYPE_TQP5  || type == GGML_TYPE_TQP6 || type == GGML_TYPE_TQP7;
}

bool ggml_iqk_supports_type(enum ggml_type type, enum ggml_iqk_site site) {
    if (site != GGML_IQK_SITE_DENSE && ggml_is_tq_trellis_type(type)) {
        return false;
    }
    switch (site) {
        case GGML_IQK_SITE_DENSE:
            // TQ2_0 left 2026-10-16, TQ1_0 2026-10-17, Q2_0_G128 earlier: all have dense kernels,
            // and iqk declines a type itself where it has none (k_iqk_has_tq*_kernel).
            return true;
        case GGML_IQK_SITE_MOE:
            // TQ1_0/TQ2_0 are declined callee-side (iqk_mul_mat_moe); these two have a dense
            // kernel only and the MoE row-mapping path is unexercised for them.
            return type != GGML_TYPE_Q2_0_G128 && type != GGML_TYPE_Q2_0;
        case GGML_IQK_SITE_CPU_UP_GATE:
            return type != GGML_TYPE_TQ1_0 && type != GGML_TYPE_TQ2_0
                && type != GGML_TYPE_Q2_0_G128 && type != GGML_TYPE_Q2_0;
        case GGML_IQK_SITE_UP_GATE_OP:
        case GGML_IQK_SITE_GRAPH_MOE_UP_GATE:
            return type != GGML_TYPE_TQ1_0 && type != GGML_TYPE_TQ2_0 && type != GGML_TYPE_Q2_0_G128;
        case GGML_IQK_SITE_GRAPH_FFN_UP_GATE:
            // + the Prism ternary types: no fused up/gate kernel (ik_llama.cpp #2550, MIT)
            return type != GGML_TYPE_TQ1_0 && type != GGML_TYPE_TQ2_0 && type != GGML_TYPE_Q2_0_G128
                && type != GGML_TYPE_PQ2_0 && type != GGML_TYPE_PQ2_0_R8
                && type != GGML_TYPE_PTQ1_0 && type != GGML_TYPE_PTQ1_0_R8;
        case GGML_IQK_SITE_COUNT:
            break;
    }
    return false;   // an unknown site takes nothing: declining iqk is the safe answer
}

struct ggml_tensor * ggml_moe_up_gate(
            struct ggml_context * ctx,
            struct ggml_tensor  * as_up,
            struct ggml_tensor  * as_gate,
            struct ggml_tensor  * b,
            struct ggml_tensor  * ids,
            enum   ggml_unary_op  op) {
    if (as_gate && (as_up->type != as_gate->type || !ggml_are_same_shape(as_up, as_gate)
                    || !ggml_can_fuse_up_gate_type(as_up->type))) {
        struct ggml_tensor * result_up   = ggml_mul_mat_id(ctx, as_up,   b, ids);
        struct ggml_tensor * result_gate = ggml_mul_mat_id(ctx, as_gate, b, ids);
        return ggml_fused_mul_unary(ctx, result_gate, result_up, op);
    }
    GGML_ASSERT(!ggml_is_transposed(as_up));
    GGML_ASSERT(!as_gate || !ggml_is_transposed(as_gate));
    GGML_ASSERT(ids->type == GGML_TYPE_I32);

    GGML_ASSERT(as_up->ne[3] == 1); // as is 3d (one matrix per expert)
    GGML_ASSERT(b->ne[3] == 1); // b is 3d
    GGML_ASSERT(ids->ne[2] == 1 && ids->ne[3] == 1); // ids is 2d
    GGML_ASSERT(ids->ne[1] == b->ne[2]); // must have an expert list per b row
    GGML_ASSERT(as_up->ne[0] == b->ne[0]); // can_mul_mat
    GGML_ASSERT(ids->ne[0] % b->ne[1] == 0); // can broadcast



    const int64_t ne[4] = { as_gate ? as_up->ne[1] : as_up->ne[1]/2, ids->ne[0], b->ne[2], 1 };
    struct ggml_tensor * result = ggml_new_tensor(ctx, GGML_TYPE_F32, 4, ne);

    result->op   = GGML_OP_MOE_FUSED_UP_GATE;
    result->src[0] = as_up;
    result->src[1] = as_gate;
    result->src[2] = b;
    result->src[3] = ids;
    result->src[4] = NULL;
    result->src[5] = NULL;

    ggml_set_op_params_i32(result, 0, (int32_t) op);

    return result;
}

struct ggml_tensor * ggml_moe_up_gate_ext(
            struct ggml_context * ctx,
            struct ggml_tensor  * as_up,
            struct ggml_tensor  * as_gate,
            struct ggml_tensor  * b,
            struct ggml_tensor  * ids,
            struct ggml_tensor  * as_up_b,
            struct ggml_tensor  * as_gate_b,
            enum   ggml_unary_op  op) {

    if (!as_up_b && !as_gate_b) {
        return ggml_moe_up_gate(ctx, as_up, as_gate, b, ids, op);
    }

    // THIRD fusion site, and it needs the type predicate independently. The delegation above
    // only fires when BOTH biases are null; with a bias present this function makes its own
    // fusion decision and never reaches ggml_moe_up_gate's guard.
    if (as_gate && (as_up->type != as_gate->type || !ggml_are_same_shape(as_up, as_gate)
                    || !ggml_can_fuse_up_gate_type(as_up->type))) {
        struct ggml_tensor * result_up   = ggml_mul_mat_id(ctx, as_up,   b, ids);
        if (as_up_b) {
            result_up = ggml_add_id(ctx, result_up, as_up_b, ids);
        }
        struct ggml_tensor * result_gate = ggml_mul_mat_id(ctx, as_gate, b, ids);
        if (as_gate_b) {
            result_gate = ggml_add_id(ctx, result_gate, as_gate_b, ids);
        }
        return ggml_fused_mul_unary(ctx, result_gate, result_up, op);
    }

    GGML_ASSERT(!ggml_is_transposed(as_up));
    GGML_ASSERT(!as_gate || !ggml_is_transposed(as_gate));
    GGML_ASSERT(ids->type == GGML_TYPE_I32);

    GGML_ASSERT(as_up->ne[3] == 1); // as is 3d (one matrix per expert)
    GGML_ASSERT(b->ne[3] == 1); // b is 3d
    GGML_ASSERT(ids->ne[2] == 1 && ids->ne[3] == 1); // ids is 2d
    GGML_ASSERT(ids->ne[1] == b->ne[2]); // must have an expert list per b row
    GGML_ASSERT(as_up->ne[0] == b->ne[0]); // can_mul_mat
    GGML_ASSERT(ids->ne[0] % b->ne[1] == 0); // can broadcast

    GGML_ASSERT(as_up->ne[1] == as_up_b->ne[0]);
    GGML_ASSERT(!as_gate || as_gate->ne[1] == as_gate_b->ne[0]);

    const int64_t ne[4] = { as_gate ? as_up->ne[1] : as_up->ne[1]/2, ids->ne[0], b->ne[2], 1 };
    struct ggml_tensor * result = ggml_new_tensor(ctx, GGML_TYPE_F32, 4, ne);

    result->op   = GGML_OP_MOE_FUSED_UP_GATE;
    result->src[0] = as_up;
    result->src[1] = as_gate;
    result->src[2] = b;
    result->src[3] = ids;
    result->src[4] = as_up_b;
    result->src[5] = as_gate_b;

    ggml_set_op_params_i32(result, 0, (int32_t) op);

    return result;
}

struct ggml_tensor * ggml_fused_up_gate(
            struct ggml_context * ctx,
            struct ggml_tensor  * up,
            struct ggml_tensor  * gate,
            struct ggml_tensor  * b,
            enum   ggml_unary_op  op) {
    if (!ggml_is_quantized(up->type) || up->type != gate->type || !ggml_are_same_shape(up, gate)
            || !ggml_can_fuse_up_gate_type(up->type)) {
        struct ggml_tensor * result_up   = ggml_mul_mat(ctx, up,   b);
        struct ggml_tensor * result_gate = ggml_mul_mat(ctx, gate, b);
        return ggml_fused_mul_unary(ctx, result_gate, result_up, op);
    }
    GGML_ASSERT(!ggml_is_transposed(up));
    GGML_ASSERT(!ggml_is_transposed(gate));

    GGML_ASSERT(up->ne[2] == 1); // as is 3d (one matrix per expert)
    GGML_ASSERT(up->ne[3] == 1); // as is 3d (one matrix per expert)
    GGML_ASSERT(b->ne[2] == 1); // b is 3d
    GGML_ASSERT(b->ne[3] == 1); // b is 3d
    GGML_ASSERT(up->ne[0] == b->ne[0]); // can_mul_mat


    const int64_t ne[4] = { up->ne[1], b->ne[1], 1, 1 };
    struct ggml_tensor * result = ggml_new_tensor(ctx, GGML_TYPE_F32, 4, ne);

    result->op   = GGML_OP_FUSED_UP_GATE;
    result->src[0] = up;
    result->src[1] = gate;
    result->src[2] = b;
    result->src[3] = NULL;
    result->src[4] = NULL;

    ggml_set_op_params_i32(result, 0, (int32_t) op);

    return result;
}


// ggml_out_prod

struct ggml_tensor * ggml_out_prod(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        struct ggml_tensor  * b) {
    GGML_ASSERT(ggml_can_out_prod(a, b));
    GGML_ASSERT(!ggml_is_transposed(a));



    // a is broadcastable to b for ne[2] and ne[3] -> use b->ne[2] and b->ne[3]
    const int64_t ne[4] = { a->ne[0], b->ne[0], b->ne[2], b->ne[3] };
    struct ggml_tensor * result = ggml_new_tensor(ctx, GGML_TYPE_F32, 4, ne);

    result->op   = GGML_OP_OUT_PROD;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

// ggml_scale

static struct ggml_tensor * ggml_scale_impl(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        float                 s,
        float                 b,
        bool inplace) {
    GGML_ASSERT(ggml_is_padded_1d(a));



    struct ggml_tensor * result = inplace ? ggml_view_tensor(ctx, a) : ggml_dup_tensor(ctx, a);

    float params[2] = {s, b};
    ggml_set_op_params(result, &params, sizeof(params));

    result->op   = GGML_OP_SCALE;
    result->src[0] = a;

    return result;
}

struct ggml_tensor * ggml_scale(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        float                s) {
    return ggml_scale_impl(ctx, a, s, 0.f, false);
}

struct ggml_tensor * ggml_scale_inplace(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        float                s) {
    return ggml_scale_impl(ctx, a, s, 0.f, true);
}

struct ggml_tensor * ggml_scale_bias(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        float                s,
        float                b) {
    return ggml_scale_impl(ctx, a, s, b, false);
}

struct ggml_tensor * ggml_scale_bias_inplace(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        float                s,
        float                b) {
    return ggml_scale_impl(ctx, a, s, b, true);
}

// ggml_softcap

static struct ggml_tensor * ggml_softcap_impl(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        float                 s_before,
        float                 s_after,
        bool inplace) {
    GGML_ASSERT(ggml_is_padded_1d(a));



    struct ggml_tensor * result = inplace ? ggml_view_tensor(ctx, a) : ggml_dup_tensor(ctx, a);

    float params[2] = {s_before, s_after};
    ggml_set_op_params(result, params, sizeof(params));

    result->op   = GGML_OP_SOFTCAP;
    result->src[0] = a;

    return result;
}

struct ggml_tensor * ggml_softcap(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        float                s_before,
        float                s_after) {
    return ggml_softcap_impl(ctx, a, s_before, s_after, false);
}

struct ggml_tensor * ggml_softcap_inplace(
        struct ggml_context * ctx,
        struct ggml_tensor * a,
        float                s_before,
        float                s_after) {
    return ggml_softcap_impl(ctx, a, s_before, s_after, true);
}

static struct ggml_tensor * ggml_softcap_max_impl(
            struct ggml_context * ctx,
            struct ggml_tensor  * a,
            struct ggml_tensor  * mask,
            float                 scale,
            float                 max_bias,
            float                 s_before,
            float                 s_after,
            bool                  inplace) {
    GGML_ASSERT(ggml_is_contiguous(a));
    GGML_ASSERT(ggml_is_padded_1d(a));

    if (mask) {
        GGML_ASSERT(mask->type == GGML_TYPE_F16 || mask->type == GGML_TYPE_F32);
        GGML_ASSERT(ggml_is_contiguous(mask));
        GGML_ASSERT(ggml_is_matrix(mask));
        GGML_ASSERT(mask->ne[0] == a->ne[0]);
        GGML_ASSERT(mask->ne[1] >= a->ne[1]);
    }

    if (max_bias > 0.0f) {
        GGML_ASSERT(mask);
    }



    struct ggml_tensor * result = inplace ? ggml_view_tensor(ctx, a) : ggml_dup_tensor(ctx, a);

    float params[4] = {scale, max_bias, s_before, s_after};
    ggml_set_op_params(result, params, sizeof(params));

    result->op   = GGML_OP_SOFT_CAP_MAX;
    result->src[0] = a;
    result->src[1] = mask;

    return result;
}

struct ggml_tensor * ggml_softcap_max(
            struct ggml_context * ctx,
            struct ggml_tensor  * a,
            struct ggml_tensor  * mask,
            float                 scale,
            float                 max_bias,
            float                 s_before,
            float                 s_after) {
    return ggml_softcap_max_impl(ctx, a, mask, scale, max_bias, s_before, s_after, false);
}

struct ggml_tensor * ggml_softcap_max_inplace(
            struct ggml_context * ctx,
            struct ggml_tensor  * a,
            struct ggml_tensor  * mask,
            float                 scale,
            float                 max_bias,
            float                 s_before,
            float                 s_after) {
    return ggml_softcap_max_impl(ctx, a, mask, scale, max_bias, s_before, s_after, true);
}


// ggml_set

static struct ggml_tensor * ggml_set_impl(
        struct ggml_context * ctx,
        struct ggml_tensor  * a,
        struct ggml_tensor  * b,
        size_t                nb1,
        size_t                nb2,
        size_t                nb3,
        size_t                offset,
        bool inplace) {
    GGML_ASSERT(ggml_nelements(a) >= ggml_nelements(b));



    // make a view of the destination
    struct ggml_tensor * result = inplace ? ggml_view_tensor(ctx, a) : ggml_dup_tensor(ctx, a);

    // offset goes into an int32_t op param: >= 2^31 would truncate negative and the forward would write
    // below dst (SOURCE-READ upstream 8ae38670 #30135 ggml.c:2202; upstream ggml_set_impl carries the same check)
    GGML_ASSERT(offset < (size_t)(1 << 30));
    int32_t params[] = { nb1, nb2, nb3, offset, inplace ? 1 : 0 };
    ggml_set_op_params(result, params, sizeof(params));

    result->op   = GGML_OP_SET;
    result->src[0] = a;
    result->src[1] = b;

    return result;
}

struct ggml_tensor * ggml_set(
        struct ggml_context * ctx,
        struct ggml_tensor *  a,
        struct ggml_tensor *  b,
        size_t                nb1,
        size_t                nb2,
        size_t                nb3,
        size_t                offset) {
    return ggml_set_impl(ctx, a, b, nb1, nb2, nb3, offset, false);
}

