// ggml_compute_forward_swiglu_oai

static void ggml_compute_forward_swiglu_oai_f32(
        const struct ggml_compute_params * params,
        struct ggml_tensor * dst) {

    const struct ggml_tensor * src0 = dst->src[0];
    const struct ggml_tensor * src1 = dst->src[1];
    char * src0_d = (char *) src0->data;
    char * src1_d = (char *) (src1 ? src1->data : src0->data);
    const size_t src0_o = src0->nb[1];
    const size_t src1_o = src1 ? src1->nb[1] : src0->nb[1];

    GGML_ASSERT(ggml_is_contiguous_1(src0));
    GGML_ASSERT(ggml_is_contiguous_1(dst));

    if (src1) {
        GGML_ASSERT(ggml_is_contiguous_1(src1));
        GGML_ASSERT(src0->type == src1->type);
    }

    const int ith = params->ith;
    const int nth = params->nth;

    const int nc = src1 ? src0->ne[0] : src0->ne[0] / 2;
    const int nr = ggml_nrows(src0);

    GGML_ASSERT(dst->ne[0] == nc);
    GGML_ASSERT(ggml_nrows(dst) == nr);

    const int32_t swapped = false; //ggml_get_op_params_i32(dst, 1);
    const float alpha = ggml_get_op_params_f32(dst, 2);
    const float limit = ggml_get_op_params_f32(dst, 3);

    // rows per thread
    const int dr = (nr + nth - 1)/nth;

    // row range for this thread
    const int ir0 = dr*ith;
    const int ir1 = MIN(ir0 + dr, nr);

    for (int i1 = ir0; i1 < ir1; i1++) {
        float * src0_p = (float *) (src0_d + i1*src0_o);
        float * src1_p = (float *) (src1_d + i1*src1_o);
        float * dst_p  = (float *) ((char *) dst->data + i1*(dst->nb[1]));

        if (!src1) {
            src0_p += swapped ? nc : 0;
            src1_p += swapped ? 0 : nc;
        }

        for (int k = 0; k < nc; k++) {
            const float x = MIN(src0_p[k], limit);
            const float y = MAX(MIN(src1_p[k], limit), -limit);
            const float out_glu = x / (1.f + expf(alpha * (-x)));
            dst_p[k] = out_glu * (y + 1.f);
        }

#ifndef NDEBUG
        for (int k = 0; k < nc; k++) {
            const float x = dst_p[k];
            GGML_UNUSED(x);
            assert(!isnan(x));
            assert(!isinf(x));
        }
#endif
    }
}

static void ggml_compute_forward_swiglu_oai(
        const struct ggml_compute_params * params,
        struct ggml_tensor * dst) {

    const struct ggml_tensor * src0 = dst->src[0];

    switch (src0->type) {
        case GGML_TYPE_F32:
            {
                ggml_compute_forward_swiglu_oai_f32(params, dst);
            } break;
        default:
            {
                GGML_ABORT("fatal error");
            }
    }
}

// ggml_compute_forward_fused_mul_unary

static void ggml_compute_forward_fused_mul_unary_f32(
        const struct ggml_compute_params * params,
        struct ggml_tensor * dst) {

    const struct ggml_tensor * src0 = dst->src[0];
    const struct ggml_tensor * src1 = dst->src[1];
    enum ggml_unary_op op = (enum ggml_unary_op)dst->op_params[0];
    const float limit = *(const float *)(dst->op_params + 1);

    const int ith = params->ith;
    const int nth = params->nth;

    const int nc = dst->ne[0];
    const int nr = ggml_nrows(dst);

    // rows per thread
    const int dr = (nr + nth - 1)/nth;

    // row range for this thread
    const int ir0 = dr*ith;
    const int ir1 = MIN(ir0 + dr, nr);

    if (!ggml_are_same_shape(src0, src1)) {
        GGML_ASSERT(src0->ne[0] == 1 && ggml_nrows(src0) == nr);
        GGML_ASSERT(op == GGML_UNARY_OP_SILU || op == GGML_UNARY_OP_SIGMOID);
        for (int i1 = ir0; i1 < ir1; i1++) {
            float * z = (float *) ((char *) dst->data  + i1*( dst->nb[1]));
            const float * x = (const float *) ((char *) src0->data + i1*(src0->nb[1]));
            const float * y = (const float *) ((char *) src1->data + i1*(src1->nb[1]));
            float gate = op == GGML_UNARY_OP_SILU ? ggml_silu_f32(x[0]) : 1.0f/(1.0f + expf(-x[0]));
            if (limit < 1e-6f) {
                for (int i = 0; i < nc; ++i) z[i] = gate * y[i];
            } else {
                gate = MIN(gate, limit);
                for (int i = 0; i < nc; ++i) {
                    float up = MAX(-limit, MIN(limit, y[i]));
                    z[i] = up * gate;
                }
            }
        }
        return;
    }

    GGML_ASSERT(ggml_is_contiguous_1(src0));
    GGML_ASSERT(ggml_are_same_shape(src0, dst));
    GGML_ASSERT(ggml_are_same_shape(src0, src1));
    GGML_ASSERT(op == GGML_UNARY_OP_GELU || op == GGML_UNARY_OP_RELU || op == GGML_UNARY_OP_SILU || op == GGML_UNARY_OP_SIGMOID);

    if (nr == 1 || (nr < nth && ggml_is_contiguous(src0) && ggml_is_contiguous(src1) && ggml_is_contiguous(dst))) {
        const int64_t k_block_size = 256;
        int64_t nelem = ggml_nelements(dst);
        int64_t nblock = (nelem + k_block_size - 1)/k_block_size;
        for (int64_t ib = ith; ib < nblock; ib += nth) {
            int64_t offset = ib*k_block_size;
                  float * z = (      float *) dst->data + offset;
            const float * x = (const float *)src0->data + offset;
            const float * y = (const float *)src1->data + offset;
            int n = offset + k_block_size <= nelem ? k_block_size : nelem - offset;
            switch (op) {
                case GGML_UNARY_OP_GELU: ggml_vec_gelu_f32(n, z, x); ggml_vec_mul_f32(n, z, z, y); break;
                case GGML_UNARY_OP_RELU: ggml_vec_relu_f32(n, z, x); ggml_vec_mul_f32(n, z, z, y); break;
                case GGML_UNARY_OP_SIGMOID: ggml_vec_sigmoid_mul_f32(n, x, y, z); break;
                case GGML_UNARY_OP_SILU: {
                    if (limit < 1e-6f) {
                        ggml_vec_mul_silu_f32(n, z, x, y);
                    } else {
                        // TODO: simdify this
                        for (int i = 0; i < n; ++i) {
                            float gate = ggml_silu_f32(x[i]);
                            gate = MIN(gate, limit);
                            float up = MAX(-limit, MIN(limit, y[i]));
                            z[i] = up * gate;
                        }
                    }
                } break;
                default: GGML_ABORT("fatal error");
            }
        }
        return;
    }

    for (int i1 = ir0; i1 < ir1; i1++) {
        float * z = (float *) ((char *) dst->data  + i1*( dst->nb[1]));
        const float * x = (const float *) ((char *) src0->data + i1*(src0->nb[1]));
        const float * y = (const float *) ((char *) src1->data + i1*(src1->nb[1]));
        switch (op) {
            case GGML_UNARY_OP_GELU: ggml_vec_gelu_f32(nc, z, x); ggml_vec_mul_f32(nc, z, z, y); break;
            case GGML_UNARY_OP_RELU: ggml_vec_relu_f32(nc, z, x); ggml_vec_mul_f32(nc, z, z, y); break;
            case GGML_UNARY_OP_SIGMOID: ggml_vec_sigmoid_mul_f32(nc, x, y, z); break;
            case GGML_UNARY_OP_SILU: {
                if (limit < 1e-6f) {
                    ggml_vec_mul_silu_f32(nc, z, x, y);
                } else {
                    // TODO: simdify this
                    for (int i = 0; i < nc; ++i) {
                        float gate = ggml_silu_f32(x[i]);
                        gate = MIN(gate, limit);
                        float up = MAX(-limit, MIN(limit, y[i]));
                        z[i] = up * gate;
                    }
                }
            } break;
            default: GGML_ABORT("fatal error");
        }
    }
}

static void ggml_compute_forward_fused_mul_unary(
        const struct ggml_compute_params * params,
        struct ggml_tensor * dst) {

    const struct ggml_tensor * src0 = dst->src[0];

    switch (src0->type) {
        case GGML_TYPE_F32:
            {
                ggml_compute_forward_fused_mul_unary_f32(params, dst);
            } break;
        default:
            {
                GGML_ABORT("fatal error");
            }
    }
}

// ggml_compute_forward_leaky_relu

static void ggml_compute_forward_leaky_relu_f32(
        const struct ggml_compute_params * params,
        struct ggml_tensor * dst) {

    const struct ggml_tensor * src0 = dst->src[0];

    if (params->ith != 0) {
        return;
    }

    assert(ggml_is_contiguous_1(src0));
    assert(ggml_is_contiguous_1(dst));
    assert(ggml_are_same_shape(src0, dst));

    const int n  = ggml_nrows(src0);
    const int nc = src0->ne[0];

    float negative_slope;
    memcpy(&negative_slope, dst->op_params, sizeof(float));

    assert(dst->nb[0]  == sizeof(float));
    assert(src0->nb[0] == sizeof(float));

    for (int i = 0; i < n; i++) {
        ggml_vec_leaky_relu_f32(nc,
                (float *) ((char *) dst->data  + i*( dst->nb[1])),
                (float *) ((char *) src0->data + i*(src0->nb[1])), negative_slope);
    }
}

